 (EC, "भारतीय रिज़र्व बैंक के संबंध में कथन: 1. RBI की स्थापना 1935 में हुई थी। 2. RBI की स्थापना हिल्टन यंग आयोग की सिफारिशों पर की गई थी। 3. RBI का 1959 में राष्ट्रीयकरण किया गया था। कौन-से कथन सही हैं?", ["केवल 1 और 3", "केवल 1 और 2", "1, 2 और 3", "केवल 2 और 3"], 1, "RBI — 1 अप्रैल 1935, हिल्टन यंग आयोग (1926) की सिफारिश पर। राष्ट्रीयकरण 1 जनवरी 1949 को हुआ, 1959 में नहीं।", "RBI — rbi.org.in (History)", "https://www.rbi.org.in"),
 (EC, "हरित क्रांति के दौरान किस अधिक उपज देने वाली अर्ध-बौनी धान की किस्म को \"मिरेकल राइस\" (चमत्कारी धान) कहा गया?", ["IR20", "IR8", "जया", "पद्मा"], 1, "IRRI (फिलीपींस) की IR8 किस्म (1966) को 'मिरेकल राइस' कहा गया।", "IRRI — irri.org", "https://www.irri.org"),
 (MA, "एक उत्पाद पर उसके क्रय मूल्य से 20% अधिक मूल्य अंकित किया जाता है और 10% की छूट पर बेचा जाता है। यदि अर्जित लाभ ₹400 है, तो उत्पाद का क्रय मूल्य क्या है?", ["₹5,500", "₹4,800", "₹4,000", "₹5,000"], 3, "क्रय मूल्य = x, अंकित = 1.2x, विक्रय = 1.2x × 0.9 = 1.08x\nलाभ = 0.08x = 400 ⇒ x = ₹5,000", "", ""),
 (MA, "एक भिन्न 0.375 के बराबर है। यदि इसके अंश में 5 और हर में 8 जोड़े जाएँ, तो प्राप्त भिन्न 1/2 है। मूल भिन्न क्या है?", ["4/9", "9/24", "3/8", "5/9"], 2, "भिन्न = 3k/8k ⇒ (3k+5)/(8k+8) = 1/2 ⇒ 6k + 10 = 8k + 8 ⇒ k = 1\nमूल भिन्न = 3/8 (जाँच: 8/16 = 1/2)", "", ""),
 (MA, "दो उम्मीदवारों के बीच हुए चुनाव में, डाले गए कुल मतों में से 10% मत अवैध घोषित कर दिए गए। जीतने वाले उम्मीदवार ने कुल वैध मतों का 60% प्राप्त किया और वह 3600 मतों के अंतर से जीत गया। डाले गए मतों की कुल संख्या कितनी थी?", ["18000", "22000", "20000", "24000"], 2, "कुल = V, वैध = 0.9V; अंतर = (60% − 40%) × 0.9V = 0.18V = 3600\nV = 20,000", "", ""),
 (MA, "यदि 2ˣ × 3ʸ = 12 और 2ʸ × 3ˣ = 18 है, तो x + y का मान है:", ["2", "5", "3", "6"], 2, "दोनों का गुणा: 2⁽ˣ⁺ʸ⁾ × 3⁽ˣ⁺ʸ⁾ = 216 ⇒ 6⁽ˣ⁺ʸ⁾ = 6³ ⇒ x + y = 3", "", ""),
 (MA, "अनुभाग A में 25 छात्र हैं जिनका औसत प्राप्तांक 76 है। अनुभाग B में 35 छात्र हैं जिनका औसत प्राप्तांक 64 है। सभी छात्रों का संयुक्त औसत प्राप्तांक है:", ["67", "75", "72", "68"], 4, "कुल = 25×76 + 35×64 = 1900 + 2240 = 4140\nऔसत = 4140 / 60 = 69 — विकल्पों में नहीं, अतः (E)", "", ""),
 (RS, "यदि अमन, बिपिन से 5 सेमी लंबा है; बिपिन, चेतन से 3 सेमी लंबा है और चेतन, दीपक से 4 सेमी लंबा है, तो उनमें से सबसे कम लंबाई किसकी है?", ["चेतन", "दीपक", "अमन", "बिपिन"], 1, "अमन > बिपिन > चेतन > दीपक ⇒ सबसे छोटा दीपक", "", ""),
 (RS, "40 छात्रों की कक्षा में, साहिल शीर्ष से 12वें स्थान पर है। यदि मानव, साहिल से 5 स्थान नीचे है, तो नीचे से मानव का स्थान क्या है?", ["28वाँ", "22वाँ", "24वाँ", "26वाँ"], 2, "मानव ऊपर से = 12 + 5 = 17वाँ\nनीचे से = 40 − 17 + 1 = 24वाँ", "", ""),
 (RS, "किसी निश्चित कूट भाषा में, यदि 'SCHOOL' को 'MPPIDT' के रूप में कूटबद्ध किया जाता है, तो उसी कूट भाषा में 'MARKET' को किस प्रकार कूटबद्ध किया जाएगा?", ["UFKSAM", "UFLSAM", "UFKSBN", "UFLSBN"], 3, "शब्द को उल्टा लिखकर हर अक्षर +1: SCHOOL → LOOHCS → MPPIDT\nMARKET → TEKRAM → UFLSBN", "", ""),
 (RS, "यदि 'X @ Y' का अर्थ है कि X, Y का पुत्र है, 'X # Y' का अर्थ है कि X, Y की पत्नी है और 'X % Y' का अर्थ है कि X, Y का भाई है और यदि D पुरुष है, तो व्यंजक A @ B # C % D में A का D से क्या संबंध है?", ["A, D का भाई है", "A, D का पुत्र है", "A, D का पोता/नाती है", "A, D का भतीजा है"], 3, "A, B का पुत्र; B, C की पत्नी ⇒ A, C का पुत्र; C, D का भाई (D पुरुष) ⇒ A, D का भतीजा", "", ""),
 (RS, "यदि 15 अगस्त, 2023 को मंगलवार था, तो 15 अगस्त, 2024 को सप्ताह का कौन-सा दिन था?", ["बुधवार", "गुरुवार", "शुक्रवार", "शनिवार"], 1, "बीच में 29 फरवरी 2024 (लीप वर्ष) ⇒ 366 दिन = 2 विषम दिन\nमंगलवार + 2 = गुरुवार", "", ""),
 (DI, "निम्नलिखित में से किस केंद्र में उन छात्रों की संख्या सबसे अधिक है जो उत्तीर्ण नहीं हुए?", ["केंद्र E", "केंद्र B", "केंद्र C", "केंद्र D"], 3, "अनुत्तीर्ण: A 120, B 150, C 180, D 200, E 180 ⇒ सर्वाधिक केंद्र D", "", "", B1),
 (DI, "यदि केंद्र E में उपस्थित छात्रों की संख्या 20% कम हो जाती है, जबकि उत्तीर्ण होने वालों की संख्या अपरिवर्तित रहती है, तो केंद्र E में उत्तीर्ण होने वाले छात्रों का नया प्रतिशत क्या होगा?", ["90%", "100%", "85%", "80%"], 1, "नए उपस्थित = 900 × 0.8 = 720, उत्तीर्ण = 720 ⇒ 100%", "", "", B1),
 (DI, "दोनों केंद्रों B और D से उपस्थित छात्रों की कुल संख्या के कितने प्रतिशत छात्र इन दोनों केंद्रों से उत्तीर्ण हुए?", ["70%", "75%", "72%", "80%"], 1, "उपस्थित = 600 + 800 = 1400; उत्तीर्ण = 450 + 600 = 1050\n(1050/1400) × 100 = 75%", "", "", B1),
 (DI, "केंद्रों A और D से उत्तीर्ण छात्रों की कुल संख्या का केंद्रों A और D में उपस्थित छात्रों की कुल संख्या से क्या अनुपात है?", ["3 : 4", "5 : 6", "4 : 5", "2 : 3"], 0, "उत्तीर्ण = 360 + 600 = 960; उपस्थित = 480 + 800 = 1280\n960 : 1280 = 3 : 4", "", "", B1),
 (DI, "केंद्रों A और C से मिलकर उत्तीर्ण हुए छात्रों की संख्या, केंद्रों A, C और E से मिलकर उत्तीर्ण हुए छात्रों की कुल संख्या का कौन-सा अंश (भिन्न) है?", ["3/5", "5/9", "1/2", "2/3"], 1, "A + C = 360 + 540 = 900; A + C + E = 900 + 720 = 1620\n900/1620 = 5/9", "", "", B1),
 (PO, "केंद्र सरकार और एक या अधिक राज्य सरकारों के बीच विवाद सर्वोच्च न्यायालय के किस क्षेत्राधिकार (अधिकारिता) के अंतर्गत आते हैं?", ["रिट क्षेत्राधिकार", "अपीलीय क्षेत्राधिकार", "सलाहकारी क्षेत्राधिकार", "अनन्य मूल क्षेत्राधिकार"], 3, "अनुच्छेद 131 — केंद्र-राज्य व राज्य-राज्य विवाद सर्वोच्च न्यायालय के अनन्य मूल क्षेत्राधिकार में।", "भारत का संविधान, अनुच्छेद 131", CON),
 (PO, "भारतीय संविधान की सातवीं अनुसूची की किस सूची के अंतर्गत दत्तकग्रहण और उत्तराधिकार के विषय आते हैं?", ["संघ सूची", "अवशिष्ट शक्तियाँ", "समवर्ती सूची", "राज्य सूची"], 2, "समवर्ती सूची की प्रविष्टि 5 — विवाह, तलाक, दत्तकग्रहण, वसीयत, उत्तराधिकार।", "भारत का संविधान, सातवीं अनुसूची, सूची III", CON),
 (PO, "भारत के संविधान में राज्य के नीति-निदेशक तत्त्वों की अवधारणा किस देश के संविधान से ली गई है?", ["संयुक्त राज्य अमेरिका", "आयरलैंड", "सोवियत संघ", "यूनाइटेड किंगडम"], 1, "नीति-निदेशक तत्त्व (भाग IV) आयरलैंड के संविधान से प्रेरित हैं।", "NCERT कक्षा 11 'भारत का संविधान: सिद्धांत और व्यवहार'", NC),
 (PO, "राज्य सभा को धन विधेयक प्राप्त होने की तिथि के कितने दिनों के भीतर उसे लोक सभा को वापस करना होता है?", ["21 दिन", "14 दिन", "10 दिन", "15 दिन"], 1, "अनुच्छेद 109 — राज्य सभा को 14 दिन में धन विधेयक लौटाना होता है, अन्यथा पारित माना जाता है।", "भारत का संविधान, अनुच्छेद 109", CON),
 (PO, "सूची I (केंद्र-शासित प्रदेश) को सूची II (गठन वर्ष) से सुमेलित कीजिए:\na. लद्दाख  b. चंडीगढ़  c. अंडमान और निकोबार द्वीपसमूह  d. दादरा और नगर हवेली और दमन और दीव\ni. 2019  ii. 1956  iii. 1966  iv. 2020", ["a-i, b-iii, c-ii, d-iv", "a-i, b-ii, c-iii, d-iv", "a-iii, b-ii, c-iv, d-i", "a-i, b-ii, c-iv, d-iii"], 0, "लद्दाख — 2019 (i); चंडीगढ़ — 1966, पंजाब पुनर्गठन (iii); अंडमान-निकोबार — 1956 (ii); DNH&DD — 26 जनवरी 2020 (iv)।", "गृह मंत्रालय; भारत का संविधान, प्रथम अनुसूची", "https://www.mha.gov.in"),
 (DI, "संयंत्रों B और D में निर्मित इकाइयों की कुल संख्या सभी पाँच संयंत्रों में निर्मित इकाइयों की कुल संख्या का कितना प्रतिशत थी?", ["35.50%", "48.25%", "40.25%", "50.50%"], 4, "B + D = 750 + 900 = 1650\n(1650/4000) × 100 = 41.25% — विकल्पों में नहीं, अतः (E)", "", "", T1),
 (DI, "प्रति संयंत्र निर्मित इकाइयों की औसत संख्या और प्रति संयंत्र गुणवत्ता निरीक्षण में सफल होने वाली इकाइयों की औसत संख्या के बीच क्या अंतर है?", ["148", "160", "152", "144"], 2, "औसत निर्मित = 4000/5 = 800; औसत सफल = 3240/5 = 648\nअंतर = 152", "", "", T1),
 (DI, "संयंत्र C में निर्मित कुल इकाइयों का कितना प्रतिशत गुणवत्ता निरीक्षण में सफल हुआ?", ["85%", "80%", "82%", "87%"], 0, "(680/800) × 100 = 85%", "", "", T1),
 (DI, "संयंत्र B में गुणवत्ता निरीक्षण में असफल इकाइयों की संख्या का संयंत्र D में गुणवत्ता निरीक्षण में असफल इकाइयों की संख्या से अनुपात क्या है?", ["4 : 5", "5 : 6", "6 : 7", "3 : 4"], 1, "B असफल = 750 − 600 = 150; D असफल = 900 − 720 = 180\n150 : 180 = 5 : 6", "", "", T1),
 (DI, "संयंत्र C में 40 ऐसी इकाइयाँ, जो प्रारंभिक गुणवत्ता निरीक्षण में असफल हो गई थीं, पुनः निरीक्षण के बाद सफल हो गईं। संयंत्र C में निर्मित कुल इकाइयों में से अंततः गुणवत्ता निरीक्षण में सफल इकाइयों का अंश (भिन्न) क्या है?", ["7/20", "11/20", "9/10", "19/20"], 2, "सफल = 680 + 40 = 720\n720/800 = 9/10", "", "", T1),
 (HI, "निम्नलिखित में से किसने 1906 में अंग्रेज़ी दैनिक समाचार-पत्र 'बंदे मातरम्' का प्रकाशन शुरू किया?", ["दादाभाई नौरोजी", "सुरेंद्रनाथ बनर्जी", "रवींद्रनाथ टैगोर", "बिपिन चंद्र पाल"], 3, "बिपिन चंद्र पाल ने 1906 में 'बंदे मातरम्' (अंग्रेज़ी दैनिक) शुरू किया; बाद में अरविंद घोष संपादक बने।", "NCERT कक्षा 8 'हमारे अतीत-III'; आधुनिक भारत (स्वदेशी आंदोलन)", NC),
 (HI, "1926 में भगत सिंह, भगवती चरण वोहरा और सुखदेव थापर द्वारा किस संगठन की स्थापना की गई थी?", ["नौजवान भारत सभा", "स्वराज पार्टी", "हिंदुस्तान रिपब्लिकन एसोसिएशन", "इंडियन इंडिपेंडेंस लीग"], 0, "नौजवान भारत सभा — मार्च 1926, लाहौर। HRA 1924 (सचिंद्रनाथ सान्याल); 1928 में HSRA बना।", "NCERT कक्षा 8 'हमारे अतीत-III'", NC),
